CREATE TABLE public.hair_product_references (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),reference_key text NOT NULL UNIQUE,brand text NOT NULL CHECK (brand IN ('L''Oréal Professionnel','Milbon','J Beverly Hills','Alfaparf Milano','Kérastase Paris')),name text NOT NULL,kind text NOT NULL CHECK (kind IN ('product','collection')),category text CHECK (category IN ('Shampoo','Conditioner','Mask','Leave-in')),intended_use text NOT NULL,description text NOT NULL DEFAULT '',product_identifier text NOT NULL DEFAULT '',source_url text NOT NULL DEFAULT '',verified boolean NOT NULL DEFAULT false,suitability jsonb NOT NULL DEFAULT '{}',CHECK (NOT verified OR (kind='product' AND category IS NOT NULL AND length(trim(description))>0 AND length(trim(product_identifier))>0 AND source_url ~ '^https://')));
GRANT SELECT ON public.hair_product_references TO anon,authenticated;
GRANT ALL ON public.hair_product_references TO service_role;
ALTER TABLE public.hair_product_references ENABLE ROW LEVEL SECURITY;
CREATE POLICY reference_public_verified ON public.hair_product_references FOR SELECT TO anon,authenticated USING (verified AND kind='product');
CREATE POLICY reference_salon_review ON public.hair_product_references FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.hair_salon_admins WHERE user_id=auth.uid()));
ALTER TABLE public.hair_salon_products ADD COLUMN reference_id uuid REFERENCES public.hair_product_references(id),ADD COLUMN size text NOT NULL DEFAULT '',ADD COLUMN image_url text NOT NULL DEFAULT '',ADD COLUMN image_source text NOT NULL DEFAULT '',ADD COLUMN enabled boolean NOT NULL DEFAULT false,ADD COLUMN available boolean NOT NULL DEFAULT false;
CREATE INDEX hair_inventory_reference_idx ON public.hair_salon_products(reference_id);
CREATE FUNCTION public.validate_hair_inventory() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE r public.hair_product_references; BEGIN IF NEW.reference_id IS NULL THEN IF NEW.enabled THEN RAISE EXCEPTION 'Select a verified individual product reference'; END IF; RETURN NEW; END IF; SELECT * INTO r FROM public.hair_product_references WHERE id=NEW.reference_id; IF r.kind <> 'product' OR NOT r.verified THEN RAISE EXCEPTION 'Only verified individual products can enter salon inventory'; END IF; IF length(trim(NEW.price))=0 OR NEW.price !~ '[0-9]' OR length(trim(NEW.size))=0 OR NEW.purchase_url !~ '^https://' OR NEW.image_url !~ '^https://' OR length(trim(NEW.image_source))=0 THEN RAISE EXCEPTION 'Provide actual retail price, size, purchase link and approved image source'; END IF; NEW.name:=r.name; NEW.brand:=r.brand; NEW.function:=r.category; NEW.description:=r.description; NEW.verified:=true; RETURN NEW; END $$;
CREATE TRIGGER hair_inventory_guard BEFORE INSERT OR UPDATE ON public.hair_salon_products FOR EACH ROW EXECUTE FUNCTION public.validate_hair_inventory();
DROP POLICY catalog_public ON public.hair_salon_products;
CREATE POLICY catalog_public ON public.hair_salon_products FOR SELECT TO anon,authenticated USING (verified AND active AND enabled AND available AND length(trim(price))>0 AND length(trim(size))>0 AND purchase_url ~ '^https://' AND image_url ~ '^https://' AND length(trim(image_source))>0 AND EXISTS (SELECT 1 FROM public.hair_product_references r WHERE r.id=reference_id AND r.verified AND r.kind='product') AND EXISTS (SELECT 1 FROM public.hair_salons s WHERE s.id=salon_id AND s.active));
COMMENT ON COLUMN public.hair_salon_products.concerns IS 'Legacy metadata; recommendations use verified reference suitability instead.';